/**
 * Brand mark (ONBOARDING_SPEC.md Pages 1-3).
 *
 * Uses the supplied logo artwork at public/brand/logo.png. An earlier version
 * pointed at an image that did not exist and fired a 404 on every page load;
 * a later version inlined a stand-in anchor glyph. Both are gone.
 *
 * The emblem has a dark teal ground of its own, so it renders as a square.
 * 256px is used rather than the full size because it is 29 KB instead of
 * 1.5 MB, which matters when the mark appears on every page of onboarding.
 * The source is left untouched and the derivatives are regenerated by
 * `npx tsx scripts/build-logo-assets.ts`.
 *
 * `.brandmark-fallback` only backstops the case where the file fails to load,
 * so a broken asset still shows the old glyph rather than an empty box.
 */
export function BrandMark({
  size = 120,
  glow = false,
  label = "MedAnchor Study logo",
}: {
  size?: number;
  glow?: boolean;
  label?: string;
}) {
  return (
    <span
      className="brandmark brandmark-fallback"
      data-glow={glow}
      style={{ width: size, height: size }}
      role="img"
      aria-label={label}
    >
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/brand/logo-256.png"
        alt=""
        width={size}
        height={size}
        draggable={false}
        style={{ width: "100%", height: "100%", objectFit: "contain", display: "block" }}
      />
    </span>
  );
}